// test: 未設定ならトークンなしでも 401
const deps = { ...(await setup()), adminToken: undefined };
assert.equal((await handleOrderExport(deps, { token: undefined, query: october })).status, 401);

interface OrderRepository {
  findByStatusUpdatedBefore(status: OrderStatus, before: Date): Promise<Order[]>; // 元のまま
  /** from 以上 to 未満に更新された注文を、状態を問わず古い順に */
  findUpdatedBetween(range: { from: Date; to: Date }): Promise<Order[]>;
}
